-- 3) de-space any stale space-mangled names in the overlay table
UPDATE `itemdisplayinfo_dbc`
SET `ModelName_1` = REPLACE(`ModelName_1`, ' ', ''), `ModelName_2` = REPLACE(`ModelName_2`, ' ', ''),
    `ModelTexture_1` = REPLACE(`ModelTexture_1`, ' ', ''), `ModelTexture_2` = REPLACE(`ModelTexture_2`, ' ', ''),
    `Texture_1` = REPLACE(`Texture_1`, ' ', ''), `Texture_2` = REPLACE(`Texture_2`, ' ', ''),
    `Texture_3` = REPLACE(`Texture_3`, ' ', ''), `Texture_4` = REPLACE(`Texture_4`, ' ', ''),
    `Texture_5` = REPLACE(`Texture_5`, ' ', ''), `Texture_6` = REPLACE(`Texture_6`, ' ', ''),
    `Texture_7` = REPLACE(`Texture_7`, ' ', ''), `Texture_8` = REPLACE(`Texture_8`, ' ', '')
WHERE CONCAT(`ModelName_1`, `ModelName_2`, `ModelTexture_1`, `ModelTexture_2`, `Texture_1`, `Texture_2`,
             `Texture_3`, `Texture_4`, `Texture_5`, `Texture_6`, `Texture_7`, `Texture_8`) LIKE '% %';


